  const routeQuery = new URLSearchParams(); if (safeReturn) routeQuery.set('returnTo', safeReturn); if (maintenance) routeQuery.set('maintenance', '1')
  const go = (suffix = '') => navigate(`/agents/${a.id}${suffix}${routeQuery.size ? `?${routeQuery}` : ''}`)
