  const requestedTab = view === 'edit' || view === 'view' ? sub ?? 'basic' : view ?? 'basic'
  const tab = state.userCenter && requestedTab === 'grants' ? 'release' : a.kind === 'team' && ['input','io','output'].includes(requestedTab) ? 'team' : simpleAssistant && ['prompt','input','output','tools','skills','matching'].includes(requestedTab) ? 'basic' : requestedTab
  const goConfig = (section: string) => go(`/${assistantReadOnly ? 'view' : 'edit'}/${section}`)
  const configTabs = simpleAssistant ? [['basic', '基础设置']] : a.kind === 'expert' ? expertConfigTabs.filter(([key]) => !isCaptain(a) || key !== 'input') : [['basic', '基本信息'], ...(a.kind === 'team' ? [['team', '队长与成员']] : [['prompt', '提示词'], ['input', '输入'], ['output', '输出'], ...(!isCaptain(a) && a.kind !== 'assistant' ? [['tools', '技能与工具']] : []), ...(a.kind === 'assistant' ? [['skills', '工作方法'], ['matching', '匹配与承接']] : [])])]
  const tabs = simpleAssistant ? [...configTabs, ['release', '让修改生效'], ...(!state.userCenter ? [['grants', '谁能使用']] : [])] : [...configTabs, ['release', '发布管理'], ...(!state.userCenter && !isCaptain(a) ? [['grants', '使用授权']] : []), ['history', '版本记录'], ['records', '运行记录']]
